// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { QueryFailure } from "../../../main/frontend/graph-explorer/request-batching.ts";
import {
  LONG_LITERAL_VALUE_ID,
  RepositoryFacetStore,
} from "../../../main/frontend/graph-explorer/repository-facets.ts";
import { BLANK_VALUE_ID } from "../../../main/frontend/graph-explorer/facet-queries.ts";

const uri = (value) => ({ type: "uri", value });
const literal = (value, extra = {}) => ({ type: "literal", value, ...extra });
const EX = "http://example.org/";

/**
 * A repository in memory that answers the store's four query shapes the way RDF4J does: per-node statements capped
 * per node, a census of predicates over capped distinct statements, probes, and per-predicate values capped per
 * predicate. `data` maps a subject IRI to [predicate, object term] pairs.
 */
function fakeRepository(data, { onQuery, fail } = {}) {
  const queries = [];
  const execute = async (query, signal) => {
    queries.push(query);
    await onQuery?.(query, signal);
    const failure = fail?.(query);
    if (failure) throw failure;
    if (signal?.aborted) throw new DOMException("aborted", "AbortError");
    const nodes = [...query.matchAll(/VALUES \?s \{ <([^>]+)> \}/g)].map((match) => match[1]);
    const limits = [...query.matchAll(/LIMIT (\d+)/g)].map((match) => Number(match[1]));
    const bindings = [];
    if (/^SELECT \?s \?p \?o/.test(query)) {
      [...new Set(nodes)].forEach((node, index) => {
        (data[node] ?? []).slice(0, limits[index]).forEach(([p, o]) => bindings.push({ s: uri(node), p: uri(p), o }));
      });
    } else if (/^SELECT \?p \(COUNT/.test(query)) {
      const counts = new Map();
      (data[nodes[0]] ?? []).slice(0, limits[0]).forEach(([p]) => counts.set(p, (counts.get(p) ?? 0) + 1));
      counts.forEach((n, p) => bindings.push({ p: uri(p), n: literal(String(n)) }));
    } else if (/^SELECT \?p WHERE/.test(query)) {
      for (const [, p] of query.matchAll(/SELECT \(<([^>]+)> AS \?p\)/g)) {
        if ((data[nodes[0]] ?? []).some(([predicate]) => predicate === p)) bindings.push({ p: uri(p) });
      }
    } else if (/^SELECT \?p \?o/.test(query)) {
      const predicates = [...query.matchAll(/SELECT DISTINCT \(<([^>]+)> AS \?p\)/g)].map((match) => match[1]);
      predicates.forEach((p, index) => {
        (data[nodes[0]] ?? []).filter(([predicate]) => predicate === p).slice(0, limits[index])
          .forEach(([, o]) => bindings.push({ p: uri(p), o }));
      });
    }
    return { results: { bindings } };
  };
  return { execute, queries };
}

/** Waits until the store has nothing queued or running. */
async function settled(store) {
  for (let turn = 0; turn < 2000; turn++) {
    if (!store.status().loading) return;
    await new Promise((resolve) => setTimeout(resolve, 1));
  }
  throw new Error("the store did not settle");
}

const requested = (query) => [...query.matchAll(/VALUES \?s \{ <([^>]+)> \}/g)].map((match) => match[1]);

test("small nodes are complete after one request; empty nodes are remembered as checked", async () => {
  const repository = fakeRepository({
    [`${EX}alice`]: [[`${EX}born`, literal("1990-04-01", { datatype: "http://www.w3.org/2001/XMLSchema#date" })], [`${EX}knows`, uri(`${EX}bob`)]],
    [`${EX}bob`]: [[`${EX}knows`, uri(`${EX}alice`)]],
  });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  store.want([`${EX}alice`, `${EX}bob`, `${EX}nobody`], "background");
  await settled(store);
  assert.equal(repository.queries.length, 1);
  const alice = store.get(`${EX}alice`);
  assert.equal(alice.predicatesComplete, true);
  assert.deepEqual(alice.predicates.get(`${EX}knows`), { values: [`${EX}bob`], complete: true });
  assert.match(alice.predicates.get(`${EX}born`).values[0], /^__rdf_literal__:/);
  assert.equal(store.get(`${EX}nobody`).predicates.size, 0, "an empty node is checked, not unknown");

  store.want([`${EX}alice`, `${EX}nobody`, `${EX}carol`], "background");
  await settled(store);
  assert.deepEqual(requested(repository.queries[1]), [`${EX}carol`], "only nodes not known yet are asked for");
});

test("values, scoped blank nodes, fixed blank references and long literals become stable value ids", async () => {
  const repository = fakeRepository({
    [`${EX}alice`]: [
      [`${EX}knows`, { type: "bnode", value: "b7" }],
      [`${EX}friend`, { type: "bnode", value: "b8", "rdf4j:reference": true }],
      [`${EX}bio`, literal("x".repeat(2000))],
    ],
  });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  store.want([`${EX}alice`], "background");
  await settled(store);
  const alice = store.get(`${EX}alice`);
  assert.deepEqual(alice.predicates.get(`${EX}knows`).values, [BLANK_VALUE_ID]);
  assert.deepEqual(alice.predicates.get(`${EX}friend`).values, ["<_:b8>"]);
  assert.deepEqual(alice.predicates.get(`${EX}bio`).values, [LONG_LITERAL_VALUE_ID]);
});

test("batches stay below the servlet's row limit and never more than two requests run at once", async () => {
  const data = {};
  for (let index = 0; index < 20; index++) data[`${EX}n${index}`] = [[`${EX}p`, literal(String(index))]];
  let running = 0;
  let most = 0;
  const repository = fakeRepository(data, {
    onQuery: async () => {
      running++;
      most = Math.max(most, running);
      await new Promise((resolve) => setTimeout(resolve, 5));
      running--;
    },
  });
  // 300 rows hold two nodes of up to 101 statements each.
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", maxRows: 300 });
  store.want(Object.keys(data), "background");
  await settled(store);
  assert.ok(repository.queries.every((query) => requested(query).length <= 2), "at most two nodes per request");
  assert.equal(most, 2, "two requests in flight, never more");
  assert.equal(Object.keys(data).filter((id) => store.get(id)).length, 20);
});

test("background loading waits while the explorer's own queries run", async () => {
  const repository = fakeRepository({ [`${EX}a`]: [[`${EX}p`, literal("1")]] });
  let release;
  const busy = new Promise((resolve) => (release = resolve));
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", foreground: { idle: () => busy } });
  store.want([`${EX}a`], "background");
  await new Promise((resolve) => setTimeout(resolve, 20));
  assert.equal(repository.queries.length, 0, "nothing is sent while a foreground query runs");
  release();
  await settled(store);
  assert.equal(repository.queries.length, 1);
});

test("a large node is counted per predicate and its values come per predicate, capped at 1,000", async () => {
  const hub = `${EX}hub`;
  const statements = [];
  for (let index = 0; index < 1500; index++) statements.push([`${EX}tag`, literal(`t${index}`)]);
  statements.push([`${EX}rare`, literal("only once")]);
  const repository = fakeRepository({ [hub]: statements });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  store.want([hub], "background");
  await settled(store);
  const entry = store.get(hub);
  assert.equal(entry.predicatesComplete, true);
  assert.equal(entry.predicates.get(`${EX}tag`).values.length, 1000);
  assert.equal(entry.predicates.get(`${EX}tag`).complete, false, "more than 1,000 values: the cell is incomplete");
  assert.deepEqual(entry.predicates.get(`${EX}rare`), { values: [store.get(hub).predicates.get(`${EX}rare`).values[0]], complete: true });
  assert.ok(repository.queries.some((query) => /^SELECT \?p \(COUNT/.test(query)), "a census was taken");
});

test("a hub whose census stops at its cap is probed for predicates seen elsewhere", async () => {
  const hub = `${EX}hub`;
  const statements = [];
  for (let index = 0; index < 300; index++) statements.push([`${EX}tag`, literal(`t${index}`)]);
  statements.push([`${EX}rare`, literal("only once")]);
  const repository = fakeRepository({ [hub]: statements });
  const store = new RepositoryFacetStore({
    execute: repository.execute,
    scope: "default",
    censusCap: 200,
    candidates: () => [`${EX}rare`, `${EX}missing`],
  });
  store.want([hub], "background");
  await settled(store);
  const entry = store.get(hub);
  assert.ok(entry.predicates.has(`${EX}rare`), "the probe found the predicate the census did not reach");
  assert.ok(!entry.predicates.has(`${EX}missing`));
  assert.equal(entry.predicatesComplete, false, "other predicates may still be missing");
});

test("a request the servlet refuses as too large, or a reply at the row limit, is split and retried", async () => {
  const data = {};
  for (let index = 0; index < 8; index++) data[`${EX}n${index}`] = [[`${EX}p`, literal(String(index))]];
  const repository = fakeRepository(data, {
    fail: (query) => (requested(query).length > 2 ? new QueryFailure("too long", 413) : null),
  });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  store.want(Object.keys(data), "background");
  await settled(store);
  assert.equal(Object.keys(data).filter((id) => store.get(id)).length, 8);
  assert.equal(store.status().failed, 0);

  // Four nodes with three statements each reach a 12-row limit: the reply may be cut off, so it is not trusted.
  const full = {};
  for (let index = 0; index < 4; index++) full[`${EX}m${index}`] = [1, 2, 3].map((value) => [`${EX}p`, literal(String(value))]);
  const saturated = fakeRepository(full);
  const small = new RepositoryFacetStore({ execute: saturated.execute, scope: "default", maxRows: 12, perNodeCap: 3 });
  small.want(Object.keys(full), "background");
  await settled(small);
  assert.ok(saturated.queries.length > 1, "the saturated batch was asked for again in halves");
  assert.equal(Object.keys(full).filter((id) => small.get(id)?.predicates.get(`${EX}p`)?.values.length === 3).length, 4);
});

test("a reply from before a refresh is dropped and the node asked for again", async () => {
  let first = true;
  let release;
  const gate = new Promise((resolve) => (release = resolve));
  const repository = fakeRepository({ [`${EX}a`]: [[`${EX}p`, literal("1")]] }, {
    onQuery: async () => {
      if (first) {
        first = false;
        await gate;
      }
    },
  });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  store.want([`${EX}a`], "background");
  await new Promise((resolve) => setTimeout(resolve, 5));
  store.clear();
  release();
  await settled(store);
  assert.equal(repository.queries.length, 2, "the node was asked for again after the refresh");
  assert.ok(store.get(`${EX}a`));
});

test("background loading stops at the value budget; focused nodes still load", async () => {
  const data = {};
  for (let index = 0; index < 10; index++) data[`${EX}n${index}`] = [[`${EX}p`, literal(String(index))], [`${EX}q`, literal("x")]];
  const repository = fakeRepository(data);
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", budget: 4, maxRows: 300 });
  store.want(Object.keys(data), "background");
  await settled(store);
  assert.equal(store.status().budgetExhausted, true);
  assert.ok(Object.keys(data).filter((id) => store.get(id)).length < 10);
  const missing = Object.keys(data).find((id) => !store.get(id));
  store.want([missing], "focus");
  await settled(store);
  assert.ok(store.get(missing), "a focused node loads past the budget");
});

test("focused nodes are asked for before background ones", async () => {
  const data = {};
  for (let index = 0; index < 6; index++) data[`${EX}n${index}`] = [[`${EX}p`, literal(String(index))]];
  const repository = fakeRepository(data);
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", maxRows: 102, concurrency: 1 });
  store.want([`${EX}n0`, `${EX}n1`, `${EX}n2`], "background");
  store.want([`${EX}n5`], "focus");
  await settled(store);
  assert.deepEqual(requested(repository.queries[0]), [`${EX}n5`]);
});

test("stored entries are read before asking the repository, and new entries are stored", async () => {
  const repository = fakeRepository({ [`${EX}b`]: [[`${EX}p`, literal("2")]] });
  const written = new Map();
  const persistence = {
    async read(ids) {
      return new Map(ids.filter((id) => id === `${EX}a`).map((id) => [id, {
        checkedAt: Date.now(), predicatesComplete: true, predicates: [[`${EX}p`, ["stored"], true]],
      }]));
    },
    async write(entries) {
      entries.forEach((value, key) => written.set(key, value));
    },
    async clear() {},
  };
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", persistence });
  store.want([`${EX}a`, `${EX}b`], "background");
  await settled(store);
  assert.deepEqual(repository.queries.flatMap(requested), [`${EX}b`], "a stored node is not asked for");
  assert.deepEqual(store.get(`${EX}a`).predicates.get(`${EX}p`).values, ["stored"]);
  assert.ok(written.has(`${EX}b`), "the fetched node is stored");
});

test("listeners hear about new values and the version moves", async () => {
  const repository = fakeRepository({ [`${EX}a`]: [[`${EX}p`, literal("1")]] });
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default" });
  let heard = 0;
  const stop = store.subscribe(() => heard++);
  const before = store.version;
  store.want([`${EX}a`], "background");
  await settled(store);
  assert.ok(heard > 0);
  assert.ok(store.version > before);
  stop();
  store.dispose();
});

test("the store lists the predicates it has loaded, stored ones too, for the explorer to learn label predicates from", async () => {
  const LABEL = "terminusdb:///schema/star-wars#label", CHARACTER = "terminusdb:///schema/star-wars#character";
  const repository = fakeRepository({ [`${EX}film`]: [[LABEL, literal("A New Hope")], [CHARACTER, uri(`${EX}luke`)]] });
  const stored = new Map([[`${EX}planet`, { checkedAt: 0, predicatesComplete: true, predicates: [[`${EX}climate`, [], true]] }]]);
  const persistence = { read: async (ids) => new Map(ids.filter((id) => stored.has(id)).map((id) => [id, stored.get(id)])),
    write: async () => undefined, clear: async () => undefined };
  const store = new RepositoryFacetStore({ execute: repository.execute, scope: "default", persistence });
  try {
    assert.deepEqual(store.predicates(), []);
    store.want([`${EX}film`, `${EX}planet`], "focus");
    await settled(store);
    const predicates = store.predicates();
    assert.deepEqual([...predicates].sort(), [`${EX}climate`, CHARACTER, LABEL].sort());
    assert.equal(store.predicates(), predicates, "the same list until a new predicate arrives");
  } finally {
    store.dispose();
  }
});
